// Front-end templates for the try → needs → routes journey. No model is called.
(() => {
  const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const language = scene => scene === 'chinese' ? "Chinese" : "English";
  const samples = {
    english: 'Hi, I want a coffee. Can you speak slowly, please?',
    chinese: "Ni hao, wo jiao Alex. Wo xiang lianxi Zhongwen. (Hello, I'm Alex. I'd like to practice Chinese.)",
    gift: "Something small reminded me of our time together. If you feel comfortable, I would love to find a time to catch up."
  };
  const feelings = {
    english: [['hesitant',"I know some words but get stuck speaking"],['natural',"I can speak and want to sound more natural"],['beginner',"I have not started yet and want a first try"]],
    chinese: [['hesitant',"I recognize some Chinese characters but struggle to speak"],['natural',"I can say short phrases and want a more natural conversation"],['beginner',"I am a complete beginner and would like guidance"]],
    gift: [['gentle',"Show I care without putting pressure on my friend"],['words',"Find clearer words for what I want to say"],['together',"Create time together, if my friend wants that too"]]
  };
  function progress(step) {
    const steps = ["Try a little","Discover your needs","Choose a path","Find an option"];
    return `<nav class="wish-progress" aria-label="Wish exploration progress">${steps.map((s,i)=>`<span class="${i<step?'complete':i===step?'current':''}"><b>${i<step?'✓':i+1}</b>${s}</span>${i<3?'<i>—</i>':''}`).join('')}</nav>`;
  }
  function micro(scene, draft={}) {
    const gift=scene==='gift';
    return `${progress(0)}<section class="experience-panel"><div class="experience-topline"><span class="experience-badge">${gift?"♡ One sincere sentence":"Aa A one-minute first try"}</span><span class="free-label">Free · Easy to skip</span></div><h2>${gift?"Try saying one thing you want to say.":`Try one sentence in ${language(scene)}. It does not have to be perfect.`}</h2><p class="experience-lead">${gift?"Before choosing a gift, think about what you hope your friend will feel.":scene==='chinese'?"Imagine meeting a new friend. Introduce yourself in Chinese and ask them to speak slowly.":"Imagine walking into a cafe. Order a drink and ask the barista to speak slowly."}</p><div class="scenario-note"><span>${gift?'✉':'☕'}</span><p>${gift?"This is just practice. Nothing will be sent, and an unfinished sentence is welcome.":"Try the language you are learning, or write the idea in English first. You can skip this exercise."}</p></div><form id="microForm"><label for="microAnswer">${gift?"What I would like to say to my friend…":"I would try saying…"}</label><textarea id="microAnswer" rows="3" maxlength="1000" placeholder="${gift?"I remembered something we shared…":"Start with whatever you know, even if you are unsure."}">${e(draft.answer)}</textarea><button class="text-button" type="button" data-micro-example>See an example ↗</button><label for="microFeeling">${gift?"Right now, I hope to…":"Which feeling comes closest?"}</label><select id="microFeeling">${feelings[scene].map(([id,text])=>`<option value="${id}" ${draft.feeling===id?'selected':''}>${text}</option>`).join('')}</select><div class="experience-actions"><button class="subtle-btn" type="button" data-skip-micro>Skip and organize my needs</button><button class="primary-button" type="submit">Explore my needs with Momo ↗</button></div></form><p class="experience-disclosure">A preset frontend exercise based on your choices. It does not use AI assessment or evaluate language proficiency.</p></section>`;
  }
  function initialNeeds(scene, draft) {
    const gift=scene==='gift';
    const focus=gift?{gentle:"Show care with a sincere, gentle gesture and leave room for a response",words:"Find clear words first, then decide whether a gift is needed",together:"Create a relaxed moment together, only if my friend wants to meet"}:{hesitant:`Practice speaking ${language(scene)} with a patient partner who goes at my pace`,natural:`Make ${language(scene)} short phrases sound more natural in a real-life situation`,beginner:`Start learning ${language(scene)} from scratch with a few useful phrases`};
    return {focus:focus[draft.feeling]||focus[gift?'gentle':'hesitant'],budget:gift?'20':'20',schedule:'flexible'};
  }
  function needs(scene, draft, need) {
    const selected=feelings[scene].find(([id])=>id===draft.feeling)?.[1]||"Using the wish you shared";
    return `${progress(1)}<section class="experience-panel needs-panel"><div class="experience-topline"><span class="experience-badge">✧ An editable wish card</span><span class="free-label">You decide</span></div><h2>Let's make sure this sounds like you.</h2><p class="experience-lead">Momo made a starting point from your choices. Change anything that feels off.</p><div class="evidence-note"><span>What shaped this card?</span><p>${draft.feeling?`You chose "${e(selected)}".`:"You chose to organize your needs directly. The card keeps your original words."}${draft.answer?"Your practice sentence is here too.":"Edit the card to reflect what you want."}</p>${draft.answer?`<blockquote>${e(draft.answer)}</blockquote>`:''}</div><form id="needsForm"><label for="needFocus">What I really want to achieve</label><textarea id="needFocus" rows="2" maxlength="500" required>${e(need.focus)}</textarea><div class="need-fields"><div><label for="needBudget">My budget if I choose a paid option</label><select id="needBudget">${[['none',"No limit for now"],['0',"Free options only for now"],['15',"Up to $15"],['20',"Up to $20"],['40',"Up to $40"]].map(([v,label])=>`<option value="${v}" ${need.budget===v?'selected':''}>${label}</option>`).join('')}${!['none','0','15','20','40'].includes(need.budget)?`<option value="${e(need.budget)}" selected>Up to ${e(need.budget)}</option>`:''}</select></div><div><label for="needSchedule">Time preference</label><select id="needSchedule"><option value="flexible" ${need.schedule==='flexible'?'selected':''}>Flexible timing</option><option value="weekend" ${need.schedule==='weekend'?'selected':''}>Weekends work better</option></select></div></div><p class="field-help">Test budgets are in USD per item or session. Free paths do not lead to checkout.</p><div class="experience-actions"><button class="subtle-btn" type="button" data-retry-micro>Back to the exercise</button><button class="primary-button" type="submit">These are my needs. Show the paths ↗</button></div></form></section>`;
  }
  function pathData(scene) {
    if(scene==='gift')return [
      {id:'free',icon:'✉',title:"Find the words first",price:"$0 · Free",tag:"Start with one sincere sentence",desc:"Keep your own voice in a message that does not rush or pressure anyone. Edit it and decide whether to send it.",deliver:"You get: a message you have made your own",action:"Try writing one sentence"},
      {id:'goods',icon:'✿',title:"A small thoughtful gift",price:"Choose within your budget",tag:"Give your thought a little form",desc:"Think about shared memories and their tastes, then compare note cards, notebooks or gifts to share.",deliver:"Next: compare physical gifts",action:"Explore this path"},
      {id:'experience',icon:'☼',title:"Do one small thing together",price:"Choose within your budget",tag:"Make room to reconnect",desc:"If you both want to meet, make something together. There is no need to say everything at once.",deliver:"Next: compare shared experiences",action:"Explore this path"}
    ];
    return [
      {id:'free',icon:'Aa',title:"Practice one small step on your own",price:"$0 · Free",tag:"Start today",desc:`Use three phrases in ${language(scene)} to practice an everyday moment, then write down your next try. You do not need to buy a lesson first.`,deliver:"You get: a little card to practice again",action:"Try a free practice"},
      {id:'partner',icon:'☏',title:"Find someone to practice with",price:"Choose within your budget",tag:"A little human connection",desc:"Compare patient speaking partners and test slots. Start with one short session and see what fits.",deliver:"Next: compare one-to-one trial lessons",action:"Explore this path"},
      {id:'structured',icon:'↗',title:"Practice one real-life situation",price:"Choose within your budget",tag:"A clear small goal",desc:"Use ordering food, introductions or everyday chat as a lesson goal, then compare teaching styles.",deliver:"Next: compare situation-based tutors",action:"Explore this path"}
    ];
  }
  function paths(scene, need) {
    return `${progress(2)}<section class="routes-section"><div class="experience-topline"><span class="experience-badge">✧ One wish, a few different paths</span><button class="text-button" data-edit-needs>Edit my needs ↗</button></div><h2>Choose a way you would like to try.</h2><p class="experience-lead">There is no purchase you have to make. Choose what fits you today.</p>${summary(scene,need,null,false)}<div class="route-grid">${pathData(scene).map((p,i)=>`<article class="route-card ${p.id==='free'?'free-route':''}"><div class="route-top"><span class="route-icon">${p.icon}</span><span class="route-price">${p.price}</span></div><small>0${i+1} / ${p.tag}</small><h3>${p.title}</h3><p>${p.desc}</p><div class="route-deliver">${p.deliver}</div><button class="${p.id==='free'?'primary-button':'route-button'}" ${need.budget==='0'&&p.id!=='free'?'data-edit-needs':`data-path="${p.id}"`}>${need.budget==='0'&&p.id!=='free'?"Adjust the budget before comparing":p.action} ↗</button></article>`).join('')}</div><p class="experience-disclosure">Paid paths use a fictional test catalog and PayPal Sandbox. Exercises are preset frontend examples.</p></section>`;
  }
  function summary(scene, need, path, withButton=true) {
    if(!need)return '';
    const name=pathData(scene).find(p=>p.id===path)?.title;
    return `<div class="need-summary"><span>♡ This little wish</span><p>${e(need.focus)}</p><div class="summary-tags"><b>${need.budget==='none'?"Budget not set":need.budget==='0'?"Try it free first":`Test budget ≤ $${e(need.budget)}`}</b><b>${need.schedule==='weekend'?"Weekends work":"Flexible timing"}</b>${name?`<b>${name}</b>`:''}</div>${withButton?"<button class=\"text-button\" data-revisit-paths>Try a different path ↗</button>":''}</div>`;
  }
  function activity(scene, draft, need, savedText='') {
    const gift=scene==='gift';
    const phrases=scene==='chinese'?[["Ni hao, wo jiao Alex. (Hello, I'm Alex.)","Introduce yourself first."],["Keyi shuo man yidian ma? (Could you speak more slowly?)","Use this when you need a slower pace."],["Hen gaoxing renshi ni. (Nice to meet you.)","A natural response to keep a conversation going."]]:[['Hi, could I have a latte, please?',"Try ordering the drink you want."],['Could you say that a little more slowly?',"Ask for a slower pace when you need it."],['Thank you. Have a lovely day.',"A friendly way to finish the conversation."]];
    return `${progress(2)}<section class="experience-panel free-activity"><div class="experience-topline"><span class="experience-badge">${gift?"✉ Let the words sound like you":"Aa One little step today"}</span><span class="free-label">$0 · Free path</span></div><h2>${gift?"Write it down. Decide later whether to send it.":"Try three phrases. Keep the first step small."}</h2>${summary(scene,need,'free')}<p class="experience-lead">${gift?"Mention something specific you shared, say how you feel and leave your friend free to respond.":"This is a preset beginner exercise. Read it aloud or make the phrases your own."}</p>${gift?'':`<div class="phrase-list">${phrases.map(([phrase,tip],i)=>`<article><b>0${i+1}</b><div><strong>${phrase}</strong><p>${tip}</p></div></article>`).join('')}</div>`}<form id="freePracticeForm"><label for="practiceDraft">${gift?"A message in your own voice":"I would like to try saying"}</label><textarea id="practiceDraft" rows="4" maxlength="1200" placeholder="${gift?"Start with whichever sentence comes to mind.":"Copy a practice phrase and make it your own."}">${e(savedText||draft.answer)}</textarea><div class="experience-actions"><button class="subtle-btn" type="button" data-revisit-paths>Back to other paths</button><button class="primary-button" type="submit">${gift?"Keep these words here":"I tried it. Save this little step"} ✓</button></div></form><p class="experience-disclosure">${gift?"Nothing is sent to anyone. This text stays in the current page.":"This exercise does not use AI scoring or speech recognition and does not assess language level."}</p></section>`;
  }
  function completed(scene, need, text) {
    const gift=scene==='gift';
    return `<section class="experience-panel wish-completed"><span class="completion-flower">✳</span><div class="eyebrow">A LITTLE WISH, A LITTLE STEP</div><h2>${gift?"Your thoughts have found a little place to land.":"You took a little step toward this wish."}</h2><p>${gift?"Whether and when to send it is up to you.":"Keep practicing on your own, or explore a partner when you feel ready."}</p><blockquote>${e(text)}</blockquote><span class="free-label">A free step completed · No order created</span><div class="experience-actions"><button class="subtle-btn" data-edit-practice>Edit my words again</button><button class="primary-button" data-revisit-paths>Explore other paths ↗</button></div></section>`;
  }
  window.MOMO_EXPERIENCE = {micro,needs,paths,summary,activity,completed,initialNeeds,samples,progress,pathData};
})();
